import sys

def main():
    s = sys.stdin.read().split()[0]
    n = len(s)
    dp = [[0] * n for _ in range(n)]
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            t = s[i:j + 1]
            best = length
            for k in range(i, j):
                c = dp[i][k] + dp[k + 1][j]
                if c < best:
                    best = c
            p = (t + t).find(t, 1)
            if p < length:
                c = len(str(length // p)) + 2 + dp[i][i + p - 1]
                if c < best:
                    best = c
            dp[i][j] = best
    print(dp[0][n - 1])

main()

