import sys
from functools import lru_cache

s = sys.stdin.read().split()[0]

@lru_cache(maxsize=None)
def f(t):
    n = len(t)
    best = n
    for i in range(1, n):
        best = min(best, f(t[:i]) + f(t[i:]))
    for k in range(2, n + 1):
        if n % k == 0 and t[:n // k] * k == t:
            best = min(best, len(str(k)) + 2 + f(t[:n // k]))
    return best

print(f(s))

